using namespace cg3::cgal::internal;
CDT cdt;
for (const auto& p : points) {
    cdt.insert(CGALPoint(p.x(), p.y()));
}

std::list<CDT::Edge> border;
markDomains(cdt);

int solid_components = 0;
for (CDT::Finite_faces_iterator fit = cdt.finite_faces_begin(); fit != cdt.finite_faces_end(); ++fit) {
    if (fit->info().in_domain()) {
        bool is_solid = true;
        for (int i = 0; i < 3; ++i) {
            CDT::Edge e(fit, i);
            if (!cdt.is_constrained(e)) {
                double circumradius = cdt.circumradius(e);
                if (circumradius > alpha) {
                    is_solid = false;
                    break;
                }
            }
        }
        if (is_solid) {
            solid_components++;
        }
    }
}

return solid_components;

